const rows = $input.all().map(i => i.json);

if (rows.length === 0 || !rows[0].user_id) {
  return [{ json: { identidade_encontrada: false } }];
}

const base = rows[0];

const owners = rows
  .filter(r => r.owner_id)
  .map(r => ({ id: r.owner_id, name: r.owner_name, is_joint: r.is_joint }));

// Separa por papel (nao por ordem de criacao): individuais x perfil conjunto ("Ambos").
const individuais = owners.filter(o => !o.is_joint);
const conjunta = owners.find(o => o.is_joint) || null;
const titular1 = individuais[0] || null;
const titular2 = individuais[1] || null;

const multi_ativo = base.multi_owner_status === 'ativo';
// Escopo financeiro so precisa ser escolhido quando existe mais de uma opcao real.
const precisa_selecionar_proprietario = multi_ativo && owners.length > 1;

// Nome de quem esta falando (vem da whatsapp_contacts). Independe do escopo financeiro.
const contact_name = base.contact_name || null;
const contato_autorizado = base.contato_autorizado === true;

// O contato e o proprio titular da conta, ou uma pessoa autorizada (ex.: conjuge, filho)?
const nomeContatoNormalizado = (contact_name || '').trim().toLowerCase();
const contato_eh_titular = owners.some(
  o => (o.name || '').trim().toLowerCase() === nomeContatoNormalizado
);

// Os 3 slots so aparecem preenchidos quando a IA realmente precisa perguntar o escopo.
const owner_id_titular1 = precisa_selecionar_proprietario && titular1 ? titular1.id : 'Não existe';
const owner_nome_titular1 = precisa_selecionar_proprietario && titular1 ? titular1.name : 'Não existe';
const owner_id_titular2 = precisa_selecionar_proprietario && titular2 ? titular2.id : 'Não existe';
const owner_nome_titular2 = precisa_selecionar_proprietario && titular2 ? titular2.name : 'Não existe';
const owner_id_conjunta = precisa_selecionar_proprietario && conjunta ? conjunta.id : 'Não existe';
const owner_nome_conjunta = precisa_selecionar_proprietario && conjunta ? conjunta.name : 'Não existe';

return [{
  json: {
    identidade_encontrada: true,
    user_id: base.user_id,
    user_full_name: base.user_full_name,
    contact_name,
    contato_autorizado,
    contato_eh_titular,
    owners,
    owner_count: owners.length,
    // Quando ha escolha de escopo a fazer, owner_id fica nulo de proposito: a IA informa
    // o escopo escolhido em cada chamada de tool. Fora disso, e o titular unico da conta.
    owner_id: precisa_selecionar_proprietario ? null : (owners[0] ? owners[0].id : null),
    owner_name: precisa_selecionar_proprietario ? null : (owners[0] ? owners[0].name : null),
    precisa_selecionar_proprietario,
    owner_id_titular1,
    owner_nome_titular1,
    owner_id_titular2,
    owner_nome_titular2,
    owner_id_conjunta,
    owner_nome_conjunta
  }
}];
